import type markdownIt from 'markdown-it'
import type Token from 'markdown-it/lib/token.mjs'

import { createMarkdownRenderer, normalizeDisplayMath } from './markdown'

/**
 * 마크다운을 TTS(SpeechSynthesis)에 넣을 평문으로 바꾼다.
 *
 * 화면 렌더링과 같은 markdown-it(+KaTeX) 인스턴스로 파싱해 토큰을 순회한다.
 * - 강조/링크/제목 등 서식 마커는 버리고 텍스트만 남긴다.
 * - 링크는 표시 텍스트만, 이미지는 alt(캡션)만 읽고 URL은 읽지 않는다.
 * - 수식은 `mathToSpeech`로 읽는 문장을 만든다(기본은 TeX 명령을 벗겨 낸 대체 텍스트).
 * - 인라인 HTML은 태그를 벗겨 낸다.
 */

export type MathToSpeech = (tex: string, display: boolean) => Promise<string> | string

const MATH_INLINE_TYPES = new Set(['math_inline', 'math_inline_in_html_block'])
const MATH_BLOCK_TYPES = new Set([
  'math_block',
  'math_inline_block',
  'math_inline_bare_block',
  'math_block_in_html_block',
])

/** 문장 경계로 취급해 줄을 나누는 블록 종료 토큰. */
const BLOCK_END_TYPES = new Set([
  'paragraph_close',
  'heading_close',
  'list_item_close',
  'blockquote_close',
  'tr_close',
  'hr',
])

let md: markdownIt | null = null
function parser(): markdownIt {
  md ??= createMarkdownRenderer()
  return md
}

function stripHtmlTags(html: string): string {
  return html.replace(/<[^>]*>/g, '')
}

/**
 * SRE 없이 쓰는 대체 변환. TeX 명령 이름과 중괄호를 걷어 내 대략 읽을 수 있게 만든다.
 * `\mathbf{k}_2 = \frac{h}{2}` → `k _2 = frac h 2`
 */
export function stripTexForSpeech(tex: string): string {
  return tex
    .replace(
      /\\(?:mathbf|mathrm|mathit|mathcal|boldsymbol|text|textbf|textit|operatorname)\s*\{([^{}]*)\}/g,
      '$1'
    )
    .replace(/\\(?:left|right|quad|qquad|displaystyle)(?![a-zA-Z])|\\[,;!]/g, ' ')
    .replace(/\\([a-zA-Z]+)/g, ' $1 ')
    .replace(/[{}]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

async function walk(tokens: Token[], out: string[], mathToSpeech: MathToSpeech): Promise<void> {
  for (const token of tokens) {
    if (token.type === 'image') {
      // alt 텍스트에 서식이 있으면 children으로 들어온다. src는 읽지 않는다.
      if (token.children?.length) await walk(token.children, out, mathToSpeech)
      else out.push(token.content)
      continue
    }
    if (token.children?.length) {
      await walk(token.children, out, mathToSpeech)
      continue
    }
    if (MATH_INLINE_TYPES.has(token.type)) {
      out.push(' ', await mathToSpeech(token.content.trim(), false), ' ')
    } else if (MATH_BLOCK_TYPES.has(token.type)) {
      out.push(await mathToSpeech(token.content.trim(), true), '\n')
    } else if (token.type === 'text' || token.type === 'code_inline') {
      out.push(token.content)
    } else if (token.type === 'fence' || token.type === 'code_block') {
      out.push(token.content, '\n')
    } else if (token.type === 'html_inline') {
      out.push(stripHtmlTags(token.content))
    } else if (token.type === 'html_block') {
      out.push(stripHtmlTags(token.content), '\n')
    } else if (token.type === 'softbreak' || token.type === 'hardbreak') {
      out.push(' ')
    } else if (token.type === 'th_close' || token.type === 'td_close') {
      out.push(' ')
    } else if (BLOCK_END_TYPES.has(token.type)) {
      out.push('\n')
    }
    // 그 외(strong_open, link_open, bullet_list_open 등) 서식 마커는 무시한다.
  }
}

export async function markdownToSpeechText(
  markdown: string,
  mathToSpeech: MathToSpeech = stripTexForSpeech
): Promise<string> {
  const tokens = parser().parse(normalizeDisplayMath(markdown), { references: {} })
  const out: string[] = []
  await walk(tokens, out, mathToSpeech)
  return out
    .join('')
    .replace(/[ \t]+/g, ' ')
    .replace(/ ?\n ?/g, '\n')
    .replace(/\n{2,}/g, '\n')
    .trim()
}
