import { useCallback, useRef, useState } from 'react'

import { useQueryClient } from '@tanstack/react-query'

import { addLearningHistories } from '@/api/learningHistories'
import { useAuth } from '@/contexts/AuthContext'

import { createLearningHistoryBuffer, type SaveState } from '../lib/learning-history-buffer'

import { useForegroundDuration } from './useForegroundDuration'

export type { SaveState }

type ContentInfo = {
  owner: string
  repo: string
  path: string
  sha: string
}

export function useAddHistory(contentInfo: ContentInfo | null) {
  const { user } = useAuth()
  const queryClient = useQueryClient()
  const { getDuration, resetDuration, markActive } = useForegroundDuration()
  // eslint-disable-next-line react-hooks/purity
  const lastResultTimeRef = useRef(Date.now())
  const [saveState, setSaveState] = useState<SaveState>('idle')

  // 버퍼는 한 번만 만들고 훅 수명 동안 유지한다 (전송 실패분이 살아남아야 한다).
  const [buffer] = useState(() =>
    createLearningHistoryBuffer({
      onError: (e) => {
        // eslint-disable-next-line no-console
        console.error('Failed to save learning histories:', e)
      },
    })
  )

  const addResult = useCallback(
    (result: 'pass' | 'fail', lineNo: number) => {
      if (!contentInfo) return
      // 답을 눌렀다는 것은 페이지가 보이는 상태라는 뜻. 놓친 visible 이벤트를 여기서 보정한다.
      markActive()
      const now = Date.now()
      const duration = now - lastResultTimeRef.current
      lastResultTimeRef.current = now

      buffer.push({
        owner: contentInfo.owner,
        repo: contentInfo.repo,
        path: contentInfo.path,
        sha: contentInfo.sha,
        line_no: lineNo,
        type: result,
        duration,
      })
    },
    [buffer, contentInfo, markActive]
  )

  /**
   * 버퍼를 서버로 전송한다. 실패해도 항목은 버퍼에 남으므로 재시도할 수 있다.
   * @returns 전송 성공 여부
   */
  const flush = useCallback(async (): Promise<boolean> => {
    if (buffer.size() === 0) {
      setSaveState('idle')
      return true
    }

    setSaveState('saving')
    const ok = await buffer.flush((items) => addLearningHistories(items, user?.id))

    if (!ok) {
      setSaveState('error')
      return false
    }

    setSaveState('idle')
    await Promise.all([
      queryClient.invalidateQueries({
        queryKey: ['learningHistorySummary', contentInfo?.sha],
      }),
      queryClient.invalidateQueries({
        queryKey: ['learningHistoryBatch'],
      }),
    ])
    return true
  }, [buffer, contentInfo?.sha, queryClient, user?.id])

  /** 세션 종료: fin 행을 버퍼에 넣고 전송한다. @returns 저장 성공 여부 */
  const completeSession = useCallback(async (): Promise<boolean> => {
    if (!contentInfo) {
      // content.sha가 없으면 addResult도 no-op이라 버퍼가 비어 있다. 즉 유실될 데이터는
      // 없지만 세션이 기록되지 않은 것은 맞으므로, 조용히 넘기지 않고 남긴다.
      // eslint-disable-next-line no-console
      console.error('completeSession skipped: contentInfo is null')
      return false
    }
    const totalDuration = getDuration()

    buffer.push({
      owner: contentInfo.owner,
      repo: contentInfo.repo,
      path: contentInfo.path,
      sha: contentInfo.sha,
      line_no: -1,
      type: 'fin',
      duration: totalDuration,
    })

    resetDuration()
    lastResultTimeRef.current = Date.now()

    return flush()
  }, [buffer, contentInfo, getDuration, resetDuration, flush])

  return { addResult, completeSession, retrySave: flush, saveState, getDuration, resetDuration }
}
