import { Component, memo, Suspense, useEffect, useState, type ReactNode } from 'react'

import { useAtom } from 'jotai'
import { useNavigate } from 'react-router-dom'

import { Timer as TimerIcon } from '@mui/icons-material'
import CloseIcon from '@mui/icons-material/Close'
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  IconButton,
  LinearProgress,
  Tooltip,
  Typography,
  type BoxProps,
  mergeSlotProps,
} from '@mui/material'

import { OpacityControl } from '@/components/OpacityControl'
import { routes } from '@/routes'

import { learnConfigAtom } from '../atoms'
import type { SaveState } from '../hooks/useAddHistory'
import type { useFlashCardQuiz } from '../hooks/useFlashCardQuiz'
import type { ContentIdentifier, FlashCardContent, FlashCardItem } from '../types'
import { formatCardSourcePath } from '../utils'

import CircularProgressWithLabel from './CircularProgressWithLabel'
import { ConnectedContentNavigationBar } from './ContentNavigationBar'
import FlashCardCard from './FlashCardCard'
import LearnBlocker from './LearnBlocker'
import { RenderContextProvider } from './RenderContext'

export type QuizContainerProps = {
  className?: string
  children: ReactNode
  queryParams: { owner?: string; repo?: string; path?: string }
  quizState: ReturnType<typeof useFlashCardQuiz>
  onRestart: () => void
}

export function QuizContainer({
  className,
  children,
  queryParams,
  quizState,
  onRestart,
}: QuizContainerProps) {
  const {
    content,
    flashCardItems,
    isComplete,
    passCount,
    failCount,
    failedItems,
    total,
    elapsedSeconds,
    getDuration,
    token,
    currentIndex,
    progress,
    saveState,
    retrySave,
  } = quizState
  const navigate = useNavigate()
  const { owner, repo, path } = queryParams

  if (!content || flashCardItems.length === 0) {
    return <QuizEmptyState />
  }

  if (isComplete) {
    return (
      <QuizCompleteState
        className={className}
        passCount={passCount}
        failCount={failCount}
        total={total}
        failedItems={failedItems}
        elapsedSeconds={elapsedSeconds}
        contentId={{ owner: owner || '', repo: repo || '', path }}
        onRestart={onRestart}
        content={content}
        token={token}
        saveState={saveState}
        onRetrySave={retrySave}
      />
    )
  }

  return (
    <RenderContextProvider content={content} githubToken={token}>
      {/* 답을 하나라도 기록한 뒤부터 이탈을 막는다. 완료 화면은 이 분기 밖이라 자유롭게 이동한다. */}
      <LearnBlocker when={passCount + failCount > 0} />
      <Box
        className={className}
        sx={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          padding: 2,
          minHeight: '100vh',
        }}
      >
        <Box sx={{ display: 'flex', mb: 2 }}>
          <Box>
            <IconButton
              sx={{ transform: 'translate(-.5rem, -.2rem)' }}
              onClick={() => {
                navigate(routes.flashMan.learn.$(queryParams))
              }}
            >
              <CloseIcon />
            </IconButton>
          </Box>
          <QuizProgressBar
            sx={{ flexGrow: 1 }}
            currentIndex={currentIndex}
            total={total}
            passCount={passCount}
            failCount={failCount}
            progress={progress}
            getDuration={getDuration}
            path={path}
          />
        </Box>
        {children}
      </Box>
    </RenderContextProvider>
  )
}

export type QuizStats = BoxProps & {
  currentIndex: number
  total: number
  passCount: number
  failCount: number
  progress: number
  /** 진행 중 경과 시간(ms) getter. 표시용 tick은 QuizProgressBar가 자체 수행한다. */
  getDuration?: () => number
  path?: string
}

export function QuizEmptyState() {
  return (
    <Box sx={{ padding: 4, textAlign: 'center' }}>
      <Typography variant="body2" color="text.secondary">
        학습할 카드가 없습니다.
      </Typography>
    </Box>
  )
}

class SilentErrorBoundary extends Component<{ children: ReactNode }, { hasError: boolean }> {
  state = { hasError: false }
  static getDerivedStateFromError() {
    return { hasError: true }
  }
  render() {
    if (this.state.hasError) return null
    return this.props.children
  }
}

function getAccuracyColor(percent: number): 'success' | 'warning' | 'error' {
  if (percent >= 80) return 'success'
  if (percent >= 50) return 'warning'
  return 'error'
}

function formatDuration(seconds: number): string {
  const m = Math.floor(seconds / 60)
  const s = seconds % 60
  return m > 0 ? `${m}분 ${s}초` : `${s}초`
}

function formatClockTime(date: Date): string {
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

export function QuizCompleteState({
  className,
  passCount,
  failCount,
  total,
  elapsedSeconds,
  contentId,
  onRestart,
  failedItems = [],
  content,
  token,
  saveState = 'idle',
  onRetrySave,
}: {
  className?: string
  passCount: number
  failCount: number
  total: number
  elapsedSeconds?: number
  contentId: ContentIdentifier
  onRestart: () => void
  failedItems?: FlashCardItem[]
  content?: FlashCardContent
  token?: string
  /** 학습 기록 저장 상태. 'saving'이면 이탈 버튼을 잠그고, 'error'면 재시도를 노출한다. */
  saveState?: SaveState
  onRetrySave?: () => void
}) {
  const navigate = useNavigate()
  const accuracy = total > 0 ? Math.round((passCount / total) * 100) : 0
  const progressColor = getAccuracyColor(accuracy)
  // 저장 중 이탈하면 in-flight 요청이 끊겨 세션이 유실된다. 저장이 끝날 때까지 잠근다.
  const isSaving = saveState === 'saving'

  const renderContent = (
    <Box
      className={className}
      sx={{
        minHeight: '100dvh',
        display: 'flex',
        flexDirection: 'column',
        padding: 2,
        paddingBottom: 'max(env(safe-area-inset-bottom), 16px)',
      }}
    >
      <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
        <Button
          variant="outlined"
          disabled={isSaving}
          onClick={() => {
            navigate(routes.home.$())
          }}
        >
          Home
        </Button>
        <Box sx={{ flexGrow: 1 }} />
        <Button
          variant="outlined"
          disabled={isSaving}
          onClick={() => {
            const folderPath = contentId.path?.split('/').slice(0, -1).join('/')
            navigate(
              routes.flashMan.contents.$({
                owner: contentId.owner,
                repo: contentId.repo,
                path: folderPath || undefined,
              })
            )
          }}
        >
          폴더
        </Button>
        <Button
          variant="outlined"
          disabled={isSaving}
          onClick={() => {
            navigate(routes.flashMan.cards.$(contentId))
          }}
        >
          카드
        </Button>
        <Button
          variant="outlined"
          disabled={isSaving}
          onClick={() => {
            navigate(routes.flashMan.learn.$(contentId))
          }}
        >
          설정
        </Button>
      </Box>

      {isSaving && (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 2 }}>
          <CircularProgress size={16} />
          <Typography variant="body2" color="text.secondary">
            학습 기록 저장 중…
          </Typography>
        </Box>
      )}

      {saveState === 'error' && (
        <Alert
          severity="error"
          sx={{ mt: 2 }}
          action={
            onRetrySave && (
              <Button color="inherit" size="small" onClick={onRetrySave}>
                재시도
              </Button>
            )
          }
        >
          학습 기록을 저장하지 못했습니다. 이 화면을 벗어나면 기록이 사라질 수 있습니다.
        </Alert>
      )}

      {failedItems.length > 0 && (
        <Box sx={{ mt: 2, mb: 2 }}>
          <Typography variant="h6" sx={{ my: 2, fontWeight: 'bold' }}>
            틀린 문제 다시보기
          </Typography>
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              gap: 1,
            }}
          >
            {failedItems.map((item, i) => (
              <FlashCardCard
                key={i}
                item={item}
                sourcePath={formatCardSourcePath(contentId.owner, contentId.repo, contentId.path)}
                noteSource={
                  contentId.path && content?.sha
                    ? {
                        owner: contentId.owner,
                        repo: contentId.repo,
                        path: contentId.path,
                        sha: content.sha,
                      }
                    : null
                }
              />
            ))}
          </Box>
        </Box>
      )}

      <Box
        sx={{
          flexGrow: 1,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 1,
          py: 2,
        }}
      >
        <CircularProgressWithLabel value={accuracy} size={55} color={progressColor} />
        <Box sx={{ display: 'flex', gap: 4, alignItems: 'center' }}>
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h5" fontWeight="bold" color="success.main">
              {passCount}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              맞음
            </Typography>
          </Box>
          <Typography variant="h5" color="text.disabled">
            |
          </Typography>
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h5" fontWeight="bold" color="error.main">
              {failCount}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              틀림
            </Typography>
          </Box>
        </Box>
        {elapsedSeconds != null && elapsedSeconds > 0 && (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, color: 'text.secondary' }}>
            <TimerIcon fontSize="small" />
            <Typography variant="body2">{formatDuration(elapsedSeconds)}</Typography>
          </Box>
        )}
      </Box>

      <SilentErrorBoundary>
        <Suspense>
          <ConnectedContentNavigationBar
            contentId={contentId}
            centerButtonText="다시하기"
            onStartClick={0 < total ? onRestart : undefined}
            disabled={isSaving}
          />
        </Suspense>
      </SilentErrorBoundary>
    </Box>
  )

  if (content) {
    return (
      <RenderContextProvider content={content} githubToken={token}>
        {renderContent}
      </RenderContextProvider>
    )
  }

  return renderContent
}

export function QuizProgressBar({
  currentIndex,
  total,
  passCount,
  failCount,
  progress,
  getDuration,
  path,
  ...boxProps
}: QuizStats) {
  // const [showTimer, setShowTimer] = useState(false)
  const [{ showTimer }, setLearnConfig] = useAtom(learnConfigAtom)
  const [fileNameOpen, setFileNameOpen] = useState(false)
  const [now, setNow] = useState(() => new Date())
  const [elapsedSeconds, setElapsedSeconds] = useState(0)
  const fileName = path?.split('/').pop()

  // 시계/경과 시간 tick을 이 컴포넌트 안에서만 돌려, 매초 리렌더링 범위를
  // 진행바로 국한한다 (상위 뷰가 tick하면 열린 힌트 Dialog까지 매초 리렌더링됨).
  useEffect(() => {
    const tick = () => {
      setNow(new Date())
      if (getDuration) {
        setElapsedSeconds(Math.round(getDuration() / 1000))
      }
    }
    tick()
    const id = setInterval(tick, 1000)
    return () => clearInterval(id)
  }, [getDuration])
  return (
    <Box {...mergeSlotProps(boxProps, {})}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1, height: '30px' }}>
        <Tooltip
          title={fileName ?? ''}
          open={fileNameOpen && !!fileName}
          onClose={() => setFileNameOpen(false)}
          disableHoverListener
          disableFocusListener
          disableTouchListener
        >
          <Typography
            component="span"
            variant="body2"
            color="text.secondary"
            sx={{ marginY: 'auto', cursor: fileName ? 'pointer' : 'default' }}
            onClick={() => setFileNameOpen((prev) => !prev)}
          >
            {currentIndex + 1} / {total}
          </Typography>
        </Tooltip>
        <Box>
          {getDuration != null && (
            <Button
              size="small"
              sx={{ color: 'text.secondary' }}
              onClick={() => setLearnConfig((prev) => ({ ...prev, showTimer: !prev.showTimer }))}
            >
              {showTimer ? (
                <>
                  <Typography variant="body2" color="text.secondary">
                    {formatDuration(elapsedSeconds)}
                  </Typography>
                </>
              ) : (
                <>
                  <Typography variant="body2" color="text.secondary">
                    {formatClockTime(now)}
                  </Typography>
                </>
              )}
            </Button>
          )}
          <OpacityControl />
        </Box>
        <Typography variant="body2" sx={{ marginY: 'auto' }}>
          <Typography component="span" color="success.main">
            {passCount}
          </Typography>
          {' / '}
          <Typography component="span" color="error.main">
            {failCount}
          </Typography>
        </Typography>
      </Box>
      <LinearProgress variant="determinate" value={progress} sx={{ height: 8, borderRadius: 4 }} />
    </Box>
  )
}

function QuizSuspenseWrapperInner({ children }: { children: ReactNode }) {
  return (
    <Suspense
      fallback={
        <Box
          sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '50vh' }}
        >
          <CircularProgress />
        </Box>
      }
    >
      {children}
    </Suspense>
  )
}

export const QuizSuspenseWrapper = memo(QuizSuspenseWrapperInner)
