import { renderToString } from 'katex'

import type { Language } from '../atoms'

/**
 * LaTeX 수식을 읽어 주는 문장으로 바꾼다.
 *
 * KaTeX로 TeX → MathML을 만들고, speech-rule-engine(SRE, ChromeVox/MathJax의 수식 음성 엔진)에
 * 넣어 clearspeak 규칙으로 읽는다. 예: `\frac{a}{b}` → "b 분의 a"(ko), "a over b"(en).
 *
 * SRE 번들(약 350KB)과 로케일 JSON(약 200~380KB)은 첫 호출 시에만 동적으로 로드한다.
 * 브라우저 모드의 SRE는 기본적으로 XHR로 로케일을 받아오므로, Vite 번들에 포함된 JSON을
 * 돌려주는 커스텀 로더를 `SREfeature` 전역에 미리 넣어 둔다(로드 전에 설정해야 반영된다).
 */

type SreLocale = 'en' | 'ko'
type Sre = typeof import('speech-rule-engine')

/** SRE가 요청하는 로케일 이름 → 번들에 포함된 JSON. `base`는 항상 먼저 요청된다. */
const LOCALE_LOADERS: Record<string, () => Promise<{ default: string }>> = {
  base: () => import('speech-rule-engine/lib/mathmaps/base.json?raw'),
  euro: () => import('speech-rule-engine/lib/mathmaps/euro.json?raw'),
  en: () => import('speech-rule-engine/lib/mathmaps/en.json?raw'),
  ko: () => import('speech-rule-engine/lib/mathmaps/ko.json?raw'),
}

/** SRE에 일본어 로케일은 없다. 영어로 대체한다. */
export function sreLocaleOf(lang: Language): SreLocale {
  return lang.startsWith('ko') ? 'ko' : 'en'
}

let srePromise: Promise<Sre> | null = null
let currentLocale: SreLocale | null = null

async function loadSre(locale: SreLocale): Promise<Sre> {
  if (!srePromise) {
    ;(globalThis as { SREfeature?: unknown }).SREfeature = {
      custom: (loc: string) => {
        const loader = LOCALE_LOADERS[loc]
        return loader
          ? loader().then((m) => m.default)
          : Promise.reject(new Error(`unknown SRE locale: ${loc}`))
      },
      locale,
      domain: 'clearspeak',
      modality: 'speech',
    }
    srePromise = import('speech-rule-engine').then(async (m) => {
      // UMD 번들이라 번들러에 따라 default에 실려 올 수 있다.
      const sre = ((m as { default?: Sre }).default ?? m) as Sre
      await sre.engineReady()
      // SRE는 setupEngine마다 전역 SREfeature를 다시 병합하므로, 남겨 두면 이후 로케일 전환이 무시된다.
      // 커스텀 로더는 엔진 인스턴스에 이미 저장되어 있어 지워도 유지된다.
      delete (globalThis as { SREfeature?: unknown }).SREfeature
      currentLocale = locale
      return sre
    })
  }
  const sre = await srePromise
  if (currentLocale !== locale) {
    await sre.setupEngine({ locale })
    await sre.engineReady()
    currentLocale = locale
  }
  return sre
}

/**
 * TeX 수식을 음성용 문장으로 변환한다. KaTeX가 파싱하지 못하면 throw한다.
 * 호출자는 실패 시 `stripTexForSpeech()` 등으로 대체하면 된다.
 */
export async function texToSpeech(tex: string, display: boolean, lang: Language): Promise<string> {
  const html = renderToString(tex, {
    output: 'mathml',
    displayMode: display,
    throwOnError: false,
  })
  const mathml = html.match(/<math[\s\S]*<\/math>/)?.[0]
  if (!mathml) throw new Error('KaTeX could not parse the expression')
  const sre = await loadSre(sreLocaleOf(lang))
  return sre.toSpeech(mathml)
}
