import { useCallback, useEffect, useRef } from 'react'

import type { Language } from '../atoms'

import { texToSpeech } from './math-speech'
import { markdownToSpeechText, stripTexForSpeech } from './speech-text'

let voices: SpeechSynthesisVoice[] = []

function setVoiceList() {
  try {
    voices = window.speechSynthesis.getVoices()
  } catch {
    //
  }
}

setVoiceList()

if (window.speechSynthesis.onvoiceschanged !== undefined) {
  window.speechSynthesis.onvoiceschanged = setVoiceList
}

export function useTts(lang: Language = 'ko-KR'): (markdown: string) => Promise<void> {
  const utterRef = useRef(new SpeechSynthesisUtterance())

  useEffect(() => {
    const utter = utterRef.current
    for (let i = 0; i < voices.length; i++) {
      if (
        voices[i].lang.indexOf(lang) >= 0 ||
        voices[i].lang.indexOf(lang.replace('-', '_')) >= 0
      ) {
        utter.voice = voices[i]
        utter.lang = lang
        utter.pitch = 1
        utter.rate = 1
      }
    }
  }, [lang])

  useEffect(() => {
    return () => {
      window.speechSynthesis.cancel()
    }
  }, [])

  /**
   * 마크다운 텍스트를 읽는다. 서식·링크 URL·이미지 경로는 빼고, 수식은 SRE로 읽는 문장을 만든다.
   * 수식 변환에 실패하면(파싱 불가, SRE 로드 실패 등) TeX 명령을 벗겨 낸 텍스트로 대체한다.
   */
  const play = useCallback(
    async (markdown: string) => {
      window.speechSynthesis.cancel()
      const text = await markdownToSpeechText(markdown, (tex, display) =>
        texToSpeech(tex, display, lang).catch(() => stripTexForSpeech(tex))
      )
      if (!text) return
      return new Promise<void>((resolve) => {
        window.speechSynthesis.cancel()
        const utter = utterRef.current
        utter.text = text
        utter.onend = () => resolve()
        utter.onerror = () => resolve()
        window.speechSynthesis.speak(utter)
      })
    },
    [lang]
  )

  return play
}
