import { memo } from 'react'

import type { BoxProps } from '@mui/material'
import { Box } from '@mui/material'

import type { FlashCardNoteTarget } from '../hooks/useFlashCardNotes'

import DrawPad, { CONTROL_AREA } from './DrawPad'

export type DrawPadLayoutProps = Pick<BoxProps, 'sx'> & {
  question: string
  answer: string
  children: React.ReactNode
  clearKey?: React.Key
  noteTarget?: FlashCardNoteTarget | null
}

const SX_DRAW_PAD = {
  position: 'absolute',
  width: '100%',
  height: '100%',
}

function DrawPadLayout(props: DrawPadLayoutProps) {
  const { sx, question, answer, children, clearKey, noteTarget } = props

  return (
    <Box
      className="DrawPadLayout"
      sx={{ display: 'flex', position: 'relative', margin: '0rem 1rem', ...sx }}
    >
      <Box
        sx={{
          width: '100%',
          marginTop: `calc(${CONTROL_AREA} + .4rem)`,
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        {children}
      </Box>
      <DrawPad
        key={clearKey}
        sx={SX_DRAW_PAD}
        question={question}
        answer={answer}
        noteTarget={noteTarget}
      />
    </Box>
  )
}

export default memo(DrawPadLayout)
